fast_pseudocode:
# Grid is now a lambda — autotune tile sizes propagate to grid dimensions
@triton.autotune(
    configs=[Config({'XBLOCK': 1024, 'YBLOCK': 1}, ...), Config({'XBLOCK': 512, 'YBLOCK': 1}, ...), ...],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: constexpr, XBLOCK: constexpr):
    ...

# FIX: lambda reads META so each config gets correct grid dimensions
grid = lambda META: (cdiv(xnumel, META['XBLOCK']), cdiv(ynumel, META['YBLOCK']))
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)
